import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String cards = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();

        boolean[][] seen = new boolean[4][14];
        boolean[] duplicate = new boolean[4];
        char[] suits = {'C', 'E', 'U', 'P'};

        for (int i = 0; i < cards.length(); i += 3) {
            int value = Integer.parseInt(cards.substring(i, i + 2));
            char suit = cards.charAt(i + 2);

            int suitIndex = 0;
            while (suits[suitIndex] != suit) suitIndex++;

            if (seen[suitIndex][value]) {
                duplicate[suitIndex] = true;
            } else {
                seen[suitIndex][value] = true;
            }
        }

        StringBuilder output = new StringBuilder();
        for (int s = 0; s < 4; s++) {
            if (duplicate[s]) {
                output.append("erro");
            } else {
                int missing = 0;
                for (int value = 1; value <= 13; value++) {
                    if (!seen[s][value]) missing++;
                }
                output.append(missing);
            }
            output.append('\n');
        }

        System.out.print(output);
    }
}
